-- ============================================================================
-- CBAIMS - Official CBS Branch Directory Seed Migration (V53)
-- Ingests the complete official Bank CBS Branch Directory (~838 main branches,
-- 69 sub-branches/outlets, corporate center, and central processing).
-- Resolves exact 3-char/alphanumeric CBS branch codes to canonical districts/areas.
-- ============================================================================

-- 0. Ensure cims_branches supports regional and directory attributes
ALTER TABLE cims_branches ADD COLUMN IF NOT EXISTS canonical_district_id VARCHAR(64);
ALTER TABLE cims_branches ADD COLUMN IF NOT EXISTS area_office VARCHAR(150);
ALTER TABLE cims_branches ADD COLUMN IF NOT EXISTS area VARCHAR(150);
ALTER TABLE cims_branches ADD COLUMN IF NOT EXISTS region VARCHAR(100);
ALTER TABLE cims_branches ADD COLUMN IF NOT EXISTS city VARCHAR(100);
ALTER TABLE cims_branches ADD COLUMN IF NOT EXISTS phone VARCHAR(50);
ALTER TABLE cims_branches ADD COLUMN IF NOT EXISTS cbs_branch_code VARCHAR(50);

-- 1. Central Processing / Head Office (CBS Code 000)
VALUES ('brn-cbs-000', 'CBS-000', 'Head Office / Central Processing (CSC_CP)', 'CorporateCenter', 'org-corp-center', 'org-corp-center', 'Corporate Center', 'Corporate Center', '000', '["Corporate Banking","Retail Banking","MSME Banking","Interest-Free Banking (IFB)"]', true)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    code = EXCLUDED.code,
    canonical_district_id = EXCLUDED.canonical_district_id,
    cbs_branch_code = EXCLUDED.cbs_branch_code,
    is_active = true;

VALUES ('cbm-cbs-000', '000', 'brn-cbs-000', 'Head Office / Central Processing (CSC_CP)', 'CSC_CP,HO,000,CENTRAL', 'ACTIVE', true)
ON CONFLICT (source_branch_code) DO UPDATE SET
    cbaims_branch_id = EXCLUDED.cbaims_branch_id,
    official_name = EXCLUDED.official_name,
    aliases = EXCLUDED.aliases,
    status = EXCLUDED.status,
    is_active = true;

-- 2. Official CBS Branches (838 branches)
ON CONFLICT (id) DO UPDATE SET
    code = EXCLUDED.code,
    name = EXCLUDED.name,
    parent_district_id = EXCLUDED.parent_district_id,
    canonical_district_id = EXCLUDED.canonical_district_id,
    area_office = EXCLUDED.area_office,
    area = EXCLUDED.area,
    region = EXCLUDED.region,
    city = EXCLUDED.city,
    phone = EXCLUDED.phone,
    cbs_branch_code = EXCLUDED.cbs_branch_code,
    segment_ids = EXCLUDED.segment_ids,
    is_active = true;

-- 3. Official CBS Branch Mappings (838 mappings)
ON CONFLICT (source_branch_code) DO UPDATE SET
    cbaims_branch_id = EXCLUDED.cbaims_branch_id,
    official_name = EXCLUDED.official_name,
    aliases = EXCLUDED.aliases,
    status = EXCLUDED.status,
    is_active = true;

-- 4. District Hierarchies for CBS Branches
ON CONFLICT (id) DO UPDATE SET
    district_name = EXCLUDED.district_name,
    area_office = EXCLUDED.area_office,
    branch_name = EXCLUDED.branch_name,
    area = EXCLUDED.area,
    district_id = EXCLUDED.district_id;

-- 5. Normalized Branch Segment Assignments for CBS Branches
ON CONFLICT (branch_id, segment_id) DO NOTHING;

